def apply_template(X,color):
 h,w=len(X),len(X[0]); seed={(r,c) for r in range(h) for c in range(w) if X[r][c]==color}
 if not seed:return [row[:] for row in X]
 r0=min(r for r,c in seed);c0=min(c for r,c in seed)
 shape={(r-r0,c-c0) for r,c in seed}; out=[row[:] for row in X]
 for r in range(h):
  for c in range(w):
   coords=[(r+dr,c+dc) for dr,dc in shape]
   if all(0<=rr<h and 0<=cc<w and X[rr][cc]==0 for rr,cc in coords):
    for rr,cc in coords: out[rr][cc]=color
 return out
